let appLanguage = 'fr';
try {
  if (localStorage.getItem('kanjiSprintLanguage') === 'en') appLanguage = 'en';
} catch {}

function t(label, values = {}) {
  const phrase = appLanguage === 'en' ? englishLabels[label] ?? label : label;
  return phrase.replace(/\{(\w+)\}/g, (token, key) => values[key] ?? token);
}

function translateChrome() {
  document.documentElement.lang = appLanguage;
  const description = document.querySelector('meta[name="description"]');
  description.content = t("Révise le vocabulaire et les kanji japonais avec des quiz courts et interactifs.");
  const manifest = document.querySelector('link[rel="manifest"]');
  const manifestUrl = appLanguage === 'en' ? 'manifest.en.webmanifest?v=10' : 'manifest.webmanifest?v=7';
  if (manifest.getAttribute('href') !== manifestUrl) manifest.setAttribute('href', manifestUrl);
  document.querySelectorAll('[data-translate]').forEach(element => {
    element.textContent = t(element.dataset.translate);
  });
  document.querySelectorAll('[data-translate-label]').forEach(element => {
    element.setAttribute('aria-label', t(element.dataset.translateLabel));
  });
}

function setAppLanguage(value) {
  appLanguage = value === 'en' ? 'en' : 'fr';
  try { localStorage.setItem('kanjiSprintLanguage', appLanguage); } catch {}
  translateChrome();
}

function cardText(item, field) {
  if (!item) return '';
  if (appLanguage === 'fr') return item[field] || '';
  const authored = item.referenceVariant ? null : englishVocabulary[item.word]?.[field];
  return authored || (field === 'meaning' ? item.meaningEn : '') || item[field] || '';
}
